  const bars = rows => `<div class="lab-bars">${rows.map(([name,val,max=100])=>`<div><span>${esc(name)}</span><i><b style="width:${Math.max(1,Math.min(100,val/max*100))}%"></b></i><strong>${esc(fmt(val))}</strong></div>`).join('')}</div>`;
  const table = (heads,rows) => `<div class="lab-table-wrap"><table><thead><tr>${heads.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${esc(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
  const graph = (n,edges,active=[]) => { const pos=Array.from({length:n},(_,i)=>[220+178*Math.cos(2*Math.PI*i/n-Math.PI/2),140+110*Math.sin(2*Math.PI*i/n-Math.PI/2)]); return `<svg class="lab-graph" viewBox="0 0 440 280" role="img" aria-label="Network: numbered nodes and visible connections">${edges.map(([a,b])=>`<line x1="${pos[a][0]}" y1="${pos[a][1]}" x2="${pos[b][0]}" y2="${pos[b][1]}" stroke="#879b99" stroke-width="2"/>`).join('')}${pos.map(([x,y],i)=>`<g><circle cx="${x}" cy="${y}" r="17" fill="${active.includes(i)?'#c59550':'#254f54'}" stroke="#e6d7b5" stroke-width="2"/><text x="${x}" y="${y+5}" fill="#fff7dc" text-anchor="middle" font-size="13">${i+1}</text></g>`).join('')}</svg>`; };
