    if (!document.getElementById('atlas-lab-style')) { const style=document.createElement('style');style.id='atlas-lab-style';style.textContent=`.atlas-lab{color:inherit;font:inherit}.atlas-lab p{line-height:1.55}.lab-kicker{font-size:11px;letter-spacing:.16em;text-transform:uppercase;opacity:.7}.lab-topline{display:flex;gap:12px;align-items:flex-start}.lab-work{display:grid;grid-template-columns:minmax(0,1.45fr) minmax(220px,1fr);gap:20px;margin:18px 0}.lab-board,.lab-controls{padding:18px;border:1px solid #bba77a55;border-radius:8px;background:#c3ab7410}.atlas-lab label{display:block;font-size:13px;line-height:1.5;margin-bottom:12px}.atlas-lab select,.atlas-lab input[type=number],.atlas-lab textarea{display:block;width:100%;box-sizing:border-box;margin-top:5px;padding:9px 10px;background:#17363d;color:#faf0d7;border:1px solid #79928b;border-radius:4px;font:inherit}.atlas-lab textarea{min-height:64px}.atlas-lab button{cursor:pointer;margin:4px 5px 4px 0;padding:9px 13px;border:1px solid #b8a474;border-radius:4px;background:#244a4d;color:#fff2d4;font:inherit}.atlas-lab button:disabled{opacity:.4;cursor:default}.atlas-lab button.selected{background:#a77b39;color:#fff}.atlas-lab button:focus-visible,.atlas-lab select:focus-visible{outline:3px solid #f1cc79;outline-offset:3px}.lab-result{padding:13px 16px;border-left:3px solid #c5a667;background:#c5a66714;line-height:1.6;margin:14px 0;white-space:pre-line}.lab-bars>div{display:grid;grid-template-columns:110px 1fr 48px;align-items:center;gap:9px;font-size:12px;margin:11px 0}.lab-bars i{height:12px;background:#82908733;border-radius:6px;overflow:hidden}.lab-bars b{display:block;height:100%;background:#d0aa61}.lab-bars strong{text-align:right}.lab-table-wrap{overflow-x:auto}.atlas-lab table{border-collapse:collapse;font-size:12px;width:100%;margin:10px 0}.atlas-lab th,.atlas-lab td{text-align:left;padding:9px 7px;border-bottom:1px solid #a99b7450;vertical-align:top}.atlas-lab th{color:#d7bb7b;font-size:11px}.lab-graph{width:100%;max-height:300px}.lab-grid{display:grid;gap:5px;max-width:370px;margin:12px auto}.lab-grid button{min-width:34px;min-height:37px;margin:0;padding:5px}.lab-grid button[data-team=A]{background:#b58540}.lab-grid button[data-team=B]{background:#3b7f89}.lab-check{display:flex!important;align-items:flex-start;gap:9px;padding:9px 0}.lab-check input{margin-top:5px;flex:none}.lab-progress{font-size:12px;color:#d3b16c}.lab-image{position:relative;height:170px;background:linear-gradient(#aac0b7 0 48%,#8f9871 48% 62%,#b5a88b 62%);overflow:hidden;border-radius:5px}.lab-image .building{position:absolute;left:15%;top:28%;width:36%;height:38%;background:#aa8164;box-shadow:inset -30px 0 #785f50}.lab-image .roof{position:absolute;left:11%;top:16%;width:43%;height:20%;background:#56665d;clip-path:polygon(15% 0,84% 0,100% 100%,0 100%)}.lab-image .gate{position:absolute;left:61%;top:42%;width:25%;height:35%;border:5px solid #4b5149;box-sizing:border-box;background:repeating-linear-gradient(90deg,transparent 0 12px,#4b5149 12px 15px)}.lab-image .detect{position:absolute;left:58%;top:36%;width:32%;height:48%;border:2px solid #ffdd70;color:#ffe48d;font-size:11px;padding:2px;box-sizing:border-box}.lab-image .bench{position:absolute;left:19%;top:73%;height:8%;width:25%;background:#655444}.lab-image.night{filter:brightness(.55)}.lab-history{font-size:12px;line-height:1.6;max-height:160px;overflow:auto}.lab-finish{border-top:1px solid #b29d7050;padding-top:16px}.lab-finish select{max-width:720px}.lab-feedback{min-height:20px;color:#e8c47c;font-size:13px}@media(max-width:750px){.lab-work{grid-template-columns:1fr}.lab-board,.lab-controls{padding:12px}.lab-bars>div{grid-template-columns:90px 1fr 40px}}`;document.head.appendChild(style); }
    const st = api.state || {}; st.lab=st.lab||{}; const s=st.lab;
