    function submitAttempt(correct,reason,context=''){if(st.completed)return{replay:true,errors:attempts.errors||0,failed:false};if(failed())return{failed:true,errors:attempts.errors};const response=api.submit?.({correct,reason,encounterId:id,answer:st.transfer})||{};if(Number.isFinite(response.errors))attempts.errors=response.errors;else if(!correct)attempts.errors=(attempts.errors||0)+1;attempts.failed=!!response.failed||attempts.errors>=5;if(!correct)autoHint(attempts.errors,context);save();if(attempts.failed){sessionFailed=true;q('.lab-feedback').textContent='Five incorrect answers. This challenge is over; your completed research remains in the notebook.';lock();if(!gameOverSent){gameOverSent=true;api.gameOver?.({encounterId:id,errors:attempts.errors,reason});}}return{...response,errors:attempts.errors,failed:attempts.failed};}
