  const studentPrefs=[[0,1,2],[1,0,2],[0,1,2]],seminarPrefs=[[1,0,2],[0,1,2],[0,1,2]];
  function blockingPairs(match){const blocks=[];for(let a=0;a<3;a++)for(let b=0;b<3;b++){if(match[a]===b)continue;const assigned=match.indexOf(b);if(studentPrefs[a].indexOf(b)<studentPrefs[a].indexOf(match[a])&&(assigned<0||seminarPrefs[b].indexOf(a)<seminarPrefs[b].indexOf(assigned)))blocks.push([a,b]);}return blocks;}
  function deferred(side){const pref=side==='student'?studentPrefs:seminarPrefs,other=side==='student'?seminarPrefs:studentPrefs,next=[0,0,0],engaged=[-1,-1,-1],free=[0,1,2],steps=[];while(free.length){const a=free.shift(),b=pref[a][next[a]++],old=engaged[b];steps.push(`${side==='student'?'ABC'[a]:'XYZ'[a]} proposes to ${side==='student'?'XYZ'[b]:'ABC'[b]}`);if(old<0||other[b].indexOf(a)<other[b].indexOf(old)){engaged[b]=a;if(old>=0)free.push(old);}else free.push(a);}return{match:side==='student'?[engaged.indexOf(0),engaged.indexOf(1),engaged.indexOf(2)]:engaged,steps};}
  labs[16]=L=>{const{s}=L;s.match=s.match||[1,2,0];s.runs=s.runs||[];L.board.innerHTML=`<h3>Preference lists · capacity one each</h3>${table(['Student','Most → least preferred','Seminar','Most → least preferred'],studentPrefs.map((p,i)=>['ABC'[i],p.map(x=>'XYZ'[x]).join(' → '),'XYZ'[i],seminarPrefs[i].map(x=>'ABC'[x]).join(' → ')]))}<h3>Current assignment</h3>${s.match.map((b,a)=>select('match-'+a,'Student '+'ABC'[a],[[0,'Seminar X'],[1,'Seminar Y'],[2,'Seminar Z']],b)).join('')}${s.steps?`<div class="lab-history">${s.steps.map(esc).join('<br>')}</div>`:''}${table(['Proposing side','A / B / C assignment','Blocking pairs','Student first choices'],s.runs.map(r=>[r.side,r.match.map(x=>'XYZ'[x]).join(' / '),blockingPairs(r.match).length,r.match.filter((x,i)=>studentPrefs[i][0]===x).length]))}`;L.controls.innerHTML=button('blocking','Audit assignment for a blocking pair')+select('proposers','Deferred-acceptance proposers',[['student','Students propose'],['seminar','Seminars propose']],s.side||'student')+button('deferred','Run deferred acceptance')+`<p>Each rejected proposer tries its next option. A receiver holds the most preferred proposal so far. Preferences are complete and strict; places have capacity one.</p><p>Shapley’s theoretical contribution with Gale and Roth’s practical market design are distinct. This joint Atlas exchange is fictional.</p>`;for(let a=0;a<3;a++)L.bind('match-'+a,ev=>{s.match[a]=Number(ev.target.value);L.save();},'change');L.bind('blocking',()=>{if(!L.started())return;if(new Set(s.match).size<3){L.result('Capacity violation: each seminar has only one place. Give each student a different seminar before auditing stability.');return;}const pairs=blockingPairs(s.match);s.audited=true;if(pairs.length)s.foundBlock=true;L.result(pairs.length?`Blocking pairs: ${pairs.map(([a,b])=>'Student '+'ABC'[a]+' + seminar '+'XYZ'[b]).join('; ')}. Both sides prefer the pair to their current assignment.`:'No blocking pair under these preference lists. This establishes stability, not fairness.');L.change();});L.bind('deferred',()=>{if(!L.started())return;s.side=L.val('proposers');const run=deferred(s.side);s.match=run.match;s.steps=run.steps;s.runs.push({...run,side:s.side});L.result(`Deferred acceptance completed with ${run.steps.length} proposals and ${blockingPairs(run.match).length} blocking pairs. Changing the proposing side can change who benefits among stable allocations.`);L.change();});L.ready(()=>s.foundBlock&&s.runs.some(r=>r.side==='student')&&s.runs.some(r=>r.side==='seminar'),()=>`Identified a blocking pair, then obtained stable allocations with both student- and seminar-proposing deferred acceptance.`);
  };

  function fieldStudy(unit,spill,site){const r=rng(313),order=Array.from({length:unit==='cluster'?8:32},(_,i)=>i);for(let i=order.length-1;i>0;i--){const j=Math.floor(r()*(i+1));[order[i],order[j]]=[order[j],order[i]];}const treated=new Set(order.slice(0,order.length/2));const assignment=Array.from({length:32},(_,i)=>treated.has(unit==='cluster'?Math.floor(i/4):i));const outcomeRng=rng(917),outcomes=assignment.map((t,i)=>{const cluster=assignment.slice(Math.floor(i/4)*4,Math.floor(i/4)*4+4),exposed=!t&&cluster.some(Boolean);const prob=.25+(t?(site==='A'?.35:.10):0)+(spill&&exposed?.2:0);return Number(outcomeRng()<prob);});const a=outcomes.filter((v,i)=>assignment[i]),b=outcomes.filter((v,i)=>!assignment[i]);return{assignment,outcomes,treat:avg(a),control:avg(b),effect:avg(a)-avg(b)};}
  labs[17]=L=>{const{s}=L;s.runs=s.runs||[];const last=s.runs.at(-1);L.board.innerHTML=`<h3>Eight study clusters · four residents each</h3>${last?`<div class="lab-grid" style="grid-template-columns:repeat(8,1fr);max-width:none">${last.assignment.map((v,i)=>`<div style="padding:9px;border:1px solid #8d9e8a;background:${v?'#b2854040':'#49838b40'};text-align:center" title="Resident ${i+1}: ${v?'invited':'comparison'}; attended ${last.outcomes[i]}">${v?'T':'C'} ${last.outcomes[i]?'✓':'–'}</div>`).join('')}</div><p>T = invitation treatment; C = comparison; ✓ = simulated attendance.</p>`:'<p>Randomize assignment before inspecting outcomes. Local research partners define a countable attendance outcome.</p>'}${table(['Unit','Spillovers','Site','Treatment rate','Control rate','Difference'],s.runs.map(r=>[r.unit,r.spill?'Yes':'No',r.site,pct(r.treat),pct(r.control),pct(r.effect)]))}`;L.controls.innerHTML=select('study-outcome','Predefine the outcome',[['','Choose the target outcome…'],['attendance','Attendance recorded by independent observers'],['posts','Count online praise as if it were attendance']],s.outcome||'')+select('unit','Randomization unit',[['individual','Individual resident'],['cluster','Four-person cluster']],s.unit||'individual')+select('spill','Sharing invitations across neighbors',[['off','No spillover in this model'],['on','Spillover to untreated cluster neighbors']],s.spill?'on':'off')+select('study-site','Study population',[['A','Site A: large modeled invitation response'],['B','Site B: lower modeled invitation response']],s.site||'A')+button('randomize','Randomize and collect outcomes')+`<p>Assignment seed 313; outcome seed 917. Base attendance probability 0.25. Treatment adds 0.35 in A, 0.10 in B; spillover adds 0.20 to untreated neighbors when enabled. These are invented assumptions. Small samples remain noisy.</p>`;L.bind('randomize',()=>{if(!L.started())return;s.outcome=L.val('study-outcome');if(s.outcome!=='attendance'){L.result('Predefine an outcome that measures the attendance question directly. Online praise is a different construct.');return;}s.unit=L.val('unit');s.spill=L.val('spill')==='on';s.site=L.val('study-site');const run=fieldStudy(s.unit,s.spill,s.site);s.runs.push({...run,unit:s.unit,spill:s.spill,site:s.site});L.result(`Treatment attendance ${pct(run.treat)}; comparison ${pct(run.control)}; unadjusted difference ${pct(run.effect)}. ${s.spill?'Shared exposure can contaminate individual comparisons.':'Randomization makes the comparison informative under the stated design.'} Cluster assignment has fewer independent units; transfer to site B requires new evidence.`);L.change();});L.ready(()=>s.runs.some(r=>r.unit==='individual')&&s.runs.some(r=>r.unit==='cluster')&&s.runs.some(r=>r.spill)&&s.runs.some(r=>!r.spill)&&s.runs.some(r=>r.site==='B'),()=>`Compared individual and cluster randomization, spillovers, and a second study site using a predefined attendance outcome.`);
  };

  function institutionWorld(rule,productivity){let capital=[10,10],returns=[0,0],history=[];for(let t=0;t<5;t++){const access=rule==='shared'?[1,1]:[1,.25],investment=capital.map((c,i)=>Math.min(c*.35,5)*access[i]);const output=investment.reduce((a,b)=>a+b,0)*productivity;const shares=rule==='shared'?[.5,.5]:[.8,.2];returns=shares.map(v=>v*output);capital=capital.map((c,i)=>c-investment[i]+returns[i]);history.push({round:t+1,investment:investment.slice(),output,returns:returns.slice(),capital:capital.slice()});}return history;}
  labs[18]=L=>{const{s}=L;s.runs=s.runs||[];s.rule=s.rule||'restricted';s.productivity=s.productivity||2;const hist=institutionWorld(s.rule,s.productivity),last=hist.at(-1);L.board.innerHTML=`<h3>Five-round institutional world</h3><p>${s.rule==='shared'?'Both communities have investment access and a vote on revisions; returns split 50/50.':'Community A controls revisions; B has one-quarter investment access; returns split 80/20.'}</p>${bars([['A final capital',last.capital[0],50],['B final capital',last.capital[1],50]])}${table(['Round','A investment','B investment','Output','A return','B return'],hist.map(r=>[r.round,fmt(r.investment[0]),fmt(r.investment[1]),fmt(r.output),fmt(r.returns[0]),fmt(r.returns[1])]))}${table(['World','Productivity','A final capital','B final capital'],s.runs.map(r=>[r.rule,r.productivity,fmt(r.a),fmt(r.b)]))}`;L.controls.innerHTML=select('institution','Who can revise and access the rule?',[['restricted','Restricted access; A controls revisions'],['shared','Shared access; both communities can revise']],s.rule)+select('productivity','Output per investment unit',[[2,'2.0: reference environment'],[1.1,'1.1: rival low-productivity environment']],s.productivity)+button('society','Run five institutional rounds')+select('history-card','Inspect a historical-evidence design',[['','Choose an evidence strategy…'],['correlation','Compare only current wealth and current rules'],['discriminate','Compare documented rule changes and pre-trends, examine geography and rival shocks, and justify identification']],s.design||'')+button('historical','Inspect the design boundary')+`<p>Initial capital: 10 each. Investment = min(35% of capital, 5) × access. Output = productivity × total investment. Capital next = capital − investment + return. All parameters are original teaching assumptions.</p><p>2024 Economics prize: Acemoglu, Simon Johnson (MIT), and James A. Robinson (University of Chicago). Historical and local actors are not reducible to this two-group model.</p>`;L.bind('society',()=>{if(!L.started())return;s.rule=L.val('institution');s.productivity=Number(L.val('productivity'));const run=institutionWorld(s.rule,s.productivity),final=run.at(-1);s.runs.push({rule:s.rule,productivity:s.productivity,a:final.capital[0],b:final.capital[1]});L.result(`Final capital: A ${fmt(final.capital[0])}; B ${fmt(final.capital[1])}. Total ${fmt(final.capital[0]+final.capital[1])}. ${s.rule==='shared'?'Shared access changes both investment and distribution under these rules.':'Restricted access concentrates returns and constrains B’s investment.'} Compare the rival productivity setting before generalizing.`);L.change();});L.bind('historical',()=>{s.design=L.val('history-card');s.inspected=true;L.result(s.design==='discriminate'?'Documented changes, pre-trends, rival shocks, local actors, and explicit identification assumptions can help distinguish institutional accounts. A design still needs credible evidence; selecting it does not establish a historical causal effect.':'Current institutions and wealth can correlate for several reasons. Add historical timing, alternative causes, and an identification argument before choosing a causal account.');L.change();});L.ready(()=>s.runs.some(r=>r.rule==='restricted'&&r.productivity===2)&&s.runs.some(r=>r.rule==='shared'&&r.productivity===2)&&s.runs.some(r=>r.productivity===1.1)&&s.design==='discriminate'&&s.inspected,()=>`Compared restricted/shared access and a rival productivity setting; selected an evidence design that examines rule changes, pre-trends, and alternative causes.`);
  };

